// Criterion 5: documents past each parsing limit, generated by the test and never committed
// (m1.md, fixture list). Deterministic: the same limits give the same text. Each is otherwise a
// valid OpenAPI 3.1 document, so the only fault is the limit.
//
// The limits are ADR 0003, "Budgets", `defaultLimits`. The engine clamps every field to its
// default, so a document past the default is past every limit a caller can set.

export interface OversizeDocument {
  name: string;
  limit: 'inputBytes' | 'depth' | 'nodes' | 'aliasExpansions';
  uri: string;
  /** Built on demand: the inputBytes case is over 16 MiB. */
  text: () => string;
  /** The size the caller reports, when it differs from the text's length. */
  bytes?: number;
}

/** ADR 0003, "Budgets": the four parsing values. */
export const adrParsingLimits = {
  inputBytes: 16_777_216,
  depth: 64,
  nodes: 500_000,
  aliasExpansions: 1_000,
} as const;

const head = 'openapi: 3.1.0\ninfo:\n  title: Oversize\n  version: 1.0.0\npaths: {}\n';

export function oversizeDocuments(limits: {
  inputBytes: number; depth: number; nodes: number; aliasExpansions: number;
} = adrParsingLimits): OversizeDocument[] {
  return [
    {
      // One long description pads the text one code unit past the cap. Code units, because the
      // engine measures text length in UTF-16 code units (ADR 0003, "Budgets").
      name: 'text one code unit over inputBytes',
      limit: 'inputBytes',
      uri: 'oversize-input-bytes.yaml',
      text: () => {
        const prefix = head + 'x-padding: ';
        return prefix + 'a'.repeat(limits.inputBytes - prefix.length + 1);
      },
    },
    {
      // The caller saw from the size on disk that the file is over the cap and did not read it:
      // `text: ''` with `bytes` (ADR 0003, "Budgets").
      name: 'empty text with bytes over inputBytes, the file not read',
      limit: 'inputBytes',
      uri: 'oversize-bytes-unread.yaml',
      text: () => '',
      bytes: limits.inputBytes + 1,
    },
    {
      // Nested flow mappings, one level past the depth cap, under a vendor extension.
      name: 'nesting one level over depth',
      limit: 'depth',
      uri: 'oversize-depth.yaml',
      text: () => head + 'x-deep: ' + '{a: '.repeat(limits.depth + 1) + '1' + '}'.repeat(limits.depth + 1) + '\n',
    },
    {
      // A flow sequence of scalars, one more than the node cap (keys are not counted).
      name: 'one node over nodes',
      limit: 'nodes',
      uri: 'oversize-nodes.yaml',
      text: () => head + 'x-many: [' + Array.from({ length: limits.nodes + 1 }, () => '0').join(',') + ']\n',
    },
    {
      // One anchor and aliases to it, one more than the alias cap.
      name: 'one alias over aliasExpansions',
      limit: 'aliasExpansions',
      uri: 'oversize-aliases.yaml',
      text: () =>
        head + 'x-anchor: &a 1\nx-aliases: [' + Array.from({ length: limits.aliasExpansions + 1 }, () => '*a').join(', ') + ']\n',
    },
  ];
}
